package com.example.billing.persistence;import static com.example.billing.domain.BillingConstants.*;import com.example.billing.domain.*;import com.example.billing.persistence.Repositories.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;@Component public class BillingSeedData implements CommandLineRunner{public static final UUID SAMPLE_CUSTOMER_ID=UUID.fromString("11111111-1111-1111-1111-111111111111"),API_PLATFORM_PRODUCT_ID=UUID.fromString("22222222-2222-2222-2222-222222222222"),PRO_PLAN_ID=UUID.fromString("33333333-3333-3333-3333-333333333333");private final CustomerRepository customers;private final ProductRepository products;private final PricePlanRepository plans;public BillingSeedData(CustomerRepository c,ProductRepository p,PricePlanRepository pp){customers=c;products=p;plans=pp;}@Override @Transactional public void run(String...a){if(customers.count()>0)return;var c=new Customer();c.id=SAMPLE_CUSTOMER_ID;c.email="billing@example.com";c.companyName="Example SaaS Co";c.billingAddress="1 Billing Street";c.paymentMethodId="pm_default";c.status=CustomerStatus.ACTIVE;c.createdAt=OffsetDateTime.parse("2026-05-05T00:00:00Z");customers.save(c);var p=new Product();p.id=API_PLATFORM_PRODUCT_ID;p.name="API Platform";p.description="Usage-based API product";p.active=true;products.save(p);var plan=new PricePlan();plan.id=PRO_PLAN_ID;plan.productId=p.id;plan.billingType=BillingType.RECURRING;plan.amount=new BigDecimal("49");plan.currency="USD";plan.billingInterval=BillingInterval.MONTH;plan.usageUnit="API_CALL";plan.active=true;plans.save(plan);}}
